/**
 * A path within the Spacedrive Virtual Distributed File System
 * 
 * This is the core abstraction that enables cross-device operations.
 * An SdPath can represent:
 * - A physical file at a specific path on a specific device
 * - A content-addressed file that can be sourced from any device
 * - A sidecar (derivative data) attached to content
 * 
 * This enum-based approach enables resilient file operations by allowing
 * content-based paths to be resolved to optimal physical locations at runtime.
 */
export type SdPath = 
/**
 * A direct pointer to a file at a specific path on a specific device
 */
{ Physical: { 
/**
 * The device slug (e.g., "jamies-macbook")
 */
device_slug: string; 
/**
 * The local path on that device
 */
path: string } } | 
/**
 * A cloud storage path within a cloud volume
 */
{ Cloud: { 
/**
 * The cloud service type (S3, GoogleDrive, etc.)
 */
service: CloudServiceType; 
/**
 * The cloud identifier (bucket name, drive name, etc.)
 */
identifier: string; 
/**
 * The cloud-native path (e.g., "bucket/key" for S3)
 */
path: string } } | 
/**
 * An abstract, location-independent handle that refers to file content
 */
{ Content: { 
/**
 * The unique content identifier
 */
content_id: string } } | 
/**
 * A derivative data file (thumbnail, OCR text, embedding, etc.)
 * Sidecars are content-scoped and addressed by content + kind + variant
 */
{ Sidecar: { 
/**
 * The content this sidecar is derived from
 */
content_id: string; 
/**
 * The type of sidecar (thumb, ocr, embeddings, etc.)
 */
kind: SidecarKind; 
/**
 * The specific variant (e.g., "grid@2x", "1080p", "all-MiniLM-L6-v2")
 */
variant: SidecarVariant; 
/**
 * The storage format (webp, json, msgpack, etc.)
 */
format: SidecarFormat } };

/**
 * A batch of SdPaths, useful for operations on multiple files
 */
export type SdPathBatch = { paths: SdPath[] };

/**
 * Search facets for filtering UI
 */
export type SearchFacets = { file_types: { [key in string]: number }; 
/**
 * Content kinds by their wire name, for the filter panel's kind options.
 */
kinds: { [key in string]: number }; tags: { [key in string]: number }; date_ranges: { [key in string]: number }; size_ranges: { [key in string]: number } };

/**
 * Container for all structured filters
 */
export type SearchFilters = { file_types: string[] | null; tags: TagFilter | null; date_range: DateRangeFilter | null; size_range: SizeRangeFilter | null; content_types: ContentKind[] | null; include_hidden: boolean | null; include_archived: boolean | null; 
/**
 * Only return files that are at risk (true) or redundant (false).
 * At risk = content exists on exactly one volume.
 */
at_risk: boolean | null; 
/**
 * Only return files whose content is present on these volumes
 */
on_volumes: string[] | null; 
/**
 * Only return files whose content is NOT present on these volumes
 */
not_on_volumes: string[] | null; 
/**
 * Minimum number of distinct volumes the content must exist on
 */
min_volume_count: number | null; 
/**
 * Maximum number of distinct volumes the content can exist on
 */
max_volume_count: number | null };

/**
 * Defines the search mode and performance characteristics
 */
export type SearchMode = 
/**
 * Fast, metadata-only search (<10ms)
 */
"Fast" | 
/**
 * Normal search with semantic ranking (<100ms)
 */
"Normal" | 
/**
 * Full search with content analysis (<500ms)
 */
"Full";

/**
 * Defines the scope of the filesystem to search within
 */
export type SearchScope = 
/**
 * Search the entire library (default)
 */
"Library" | 
/**
 * Restrict search to a specific directory path and all its descendants
 */
{ Path: { path: SdPath } };

export type SearchTagsInput = { 
/**
 * Case-insensitive substring over the full path. Empty lists every tag.
 */
query: string; limit: number | null };

export type SearchTagsOutput = { tags: Tag[] };

export type SerializablePairingState = "Idle" | "GeneratingCode" | "Broadcasting" | "Scanning" | "WaitingForConnection" | "Connecting" | "Authenticating" | "ExchangingKeys" | "AwaitingConfirmation" | "EstablishingSession" | "ChallengeReceived" | "ResponsePending" | "ResponseSent" | "Completed" | { Failed: { reason: string } };

/**
 * Service configuration output
 */
export type ServiceConfigOutput = { networking_enabled: boolean; volume_monitoring_enabled: boolean; fs_watcher_enabled: boolean; statistics_listener_enabled: boolean };

/**
 * A named service under supervision.
 */
export type ServiceDefinition = (ServiceKind) & { name: string };

/**
 * How a service runs and how its liveness is judged.
 */
export type ServiceKind = 
/**
 * A long-running child process with an HTTP health endpoint. An
 * already-healthy endpoint is adopted rather than respawned.
 */
{ type: "daemon"; command: string[]; cwd: string; env?: { [key in string]: string }; health: string; dev?: boolean } | 
/**
 * A docker compose stack addressed by its project directory. Never
 * spawned as a child; lifecycle goes through the compose CLI.
 */
{ type: "compose"; dir: string; health: string; env?: { [key in string]: string } } | 
/**
 * Observed, not owned: probed and displayed, never spawned. The health
 * URL may live on another machine.
 */
{ type: "external"; health?: string | null };

export type ServiceState = { running: boolean; details: string | null };

export type ServiceStatus = { location_watcher: ServiceState; networking: ServiceState; volume_monitor: ServiceState; file_sharing: ServiceState };

export type SetNavigationFocusInput = { 
/**
 * The focus group to publish into; the default group when omitted.
 */
group?: string | null; 
/**
 * Where the window is looking, or `None` when it is showing something
 * without a path.
 */
path: SdPath | null; library_id?: string | null; 
/**
 * Label naming the publishing window, echoed back to followers.
 */
origin?: string | null };

export type SetNavigationFocusOutput = { focus: NavigationFocus; 
/**
 * False when the group was already at this position and no event went out.
 */
moved: boolean };

/**
 * Domain representation of a sidecar
 */
export type Sidecar = { id: number; content_uuid: string; kind: string; variant: string; format: string; status: string; size: number; 
/**
 * Bumped on every regeneration; sidecar URLs carry it as the cache
 * buster, since the served files are otherwise immutable to browsers.
 */
version: number; created_at: string; updated_at: string };

/**
 * Format for storing sidecar files
 * 
 * Format selection guidelines:
 * - Webp: Thumbnails and image derivatives (compressed images)
 * - Mp4: Video/audio proxies (standard media format)
 * - Json: Text-based structured data (OCR, transcripts)
 * - MessagePack: Binary structured data (embeddings, vectors)
 * - Text: Plain text extractions
 * - Ply: 3D model format for Gaussian splats
 * 
 * MessagePack is preferred for embeddings because:
 * - 6x smaller than JSON (1.7KB vs 10KB per 384-dim vector)
 * - 10x faster to parse
 * - Already used in Spacedrive (job serialization)
 * - Enables sub-30ms semantic search on 1M+ files
 */
export type SidecarFormat = "webp" | "mp_4" | "json" | "message_pack" | "text" | "ply";

export type SidecarKind = "thumb" | "thumbstrip" | "proxy" | "embeddings" | "ocr" | "transcript" | "gaussian_splat";

export type SidecarVariant = string;

export type SizeNode = { name: string; path: string; size: number; is_dir: boolean; 
/**
 * Populated for directories within the requested depth.
 */
children: SizeNode[]; 
/**
 * Direct children this directory actually has.
 */
child_count: number; 
/**
 * Bytes in children beyond the returned top-N.
 */
other_size: number; 
/**
 * Files anywhere beneath this node (1 for a file).
 */
file_count: number; 
/**
 * This directory stands for a subtree that was counted and not kept, so
 * its size is real while its children are absent until someone opens it.
 */
summarised: boolean };

/**
 * Filter for file size in bytes
 */
export type SizeRangeFilter = { min: number | null; max: number | null };

export type SizeTreeInput = { 
/**
 * Root of the tree; must live under a registered source.
 */
path: string; 
/**
 * Levels below the root to expand (clamped to 5). Defaults to 2.
 */
depth?: number | null; 
/**
 * Largest children kept per directory (clamped to 64). Defaults to 12.
 */
top?: number | null };

export type SizeTreeOutput = { root: SizeNode; attached: boolean };

/**
 * Sort direction
 */
export type SortDirection = "Asc" | "Desc";

/**
 * Fields that can be used for sorting
 */
export type SortField = "Relevance" | "Name" | "Size" | "ModifiedAt" | "CreatedAt" | "IndexedAt";

/**
 * Sorting options for search results
 */
export type SortOptions = { field: SortField; direction: SortDirection };

/**
 * A registered source of either kind.
 * 
 * `data_type` is what forks them: `filesystem` for a walked root, the
 * adapter's data type otherwise. The fields an adapter has no answer for are
 * optional rather than defaulted, so a client can tell "no root" from "root
 * unknown".
 */
export type SourceInfo = { id: string; name: string; 
/**
 * `filesystem`, or the adapter's data type.
 */
data_type: string; 
/**
 * Absent for a filesystem source: a walk has no adapter.
 */
adapter_id: string | null; 
/**
 * Records the source holds, from its last completed pass.
 */
item_count: number; last_synced: string | null; status: string; 
/**
 * Absolute root as currently mounted. Filesystem sources only.
 */
root: string | null; 
/**
 * The medium underneath, when Spacedrive tracks one.
 */
volume_uuid: string | null; 
/**
 * Whether the origin answers right now. Always true for an adapter, whose
 * origin is a network service rather than a drive in a drawer.
 */
attached: boolean; total_bytes: number | null; 
/**
 * Last time the origin answered. Absent for an adapter, whose registry
 * tracks a sync cursor rather than an attachment.
 */
last_seen_at: string | null; 
/**
 * The paired device this source was replicated from. Absent for a
 * source this library registered itself; a replica is read-only here
 * and its registry ops run on the owning device.
 */
device_id: string | null; 
/**
 * The owning device's display name, for a replica.
 */
device_label: string | null };

export type SourceItem = { id: string; external_id: string; title: string; preview: string | null; subtitle: string | null };

export type SourceMediaListingInput = { source_id: string; limit: number; offset: number };

export type SourceMediaListingOutput = { files: File[]; has_more: boolean };

export type SourceSearchInput = { query: string; 
/**
 * Restrict to one source.
 */
source_id?: string | null; 
/**
 * Restrict to one data type ("note", "email", …).
 */
data_type?: string | null; limit?: number | null };

export type SourceSearchResult = { id: string; external_id: string; record_type: string; title: string; preview: string; subtitle: string | null; snippet: string | null; rank: number; source_id: string; source_name: string; data_type: string };

